package server

import "github.com/MikeO7/kinosail/packages/httpguard"

var homeAssistantApprovalView = httpguard.NewCSRFTemplate("home-assistant-approval", `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0d0b"><title>Connect Home Assistant · Kinosail Player</title><script src="/static/theme.js?v=electric-1"></script><link rel="stylesheet" href="/static/app.css?v=skeleton-2"></head><body class="settings-page"><a class="skip" href="#main">Skip to content</a><main id="main" class="settings-shell"><a class="back" href="/settings#access">{{icon "back"}} Settings</a><header class="settings-intro"><span class="eyebrow">Local connection</span><h1>Allow Home Assistant to connect?</h1><p>Home Assistant will browse Library Content and control active Kinosail Player devices for {{.ProfileName}}.</p></header><section class="wide"><h2>Private by design</h2><p>Kinosail sends a revocable integration token. It does not share your Owner session. Media stays direct from this Server.</p><p>After approval, Kinosail returns a one-use code to <strong>{{.Destination}}</strong>.</p><form method="post" action="/home-assistant/authorize"><input type="hidden" name="request" value="{{.RequestID}}"><button name="decision" value="allow">Allow connection</button><button class="quiet" name="decision" value="deny">Cancel</button></form></section></main></body></html>`, uiIcon)
